// seed: tests/seed.spec.ts (гость, чистый контекст) · прод, только чтение (отметки — только localStorage браузера).
import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

const ITEMS = ['אימות מחזור', 'אימות רווחיות', 'שכירות', 'עובדים', 'מלאי', 'חובות', 'השקעות נדרשות', 'הוצאות נוספות'];

test.describe('Калькулятор — чек-лист и копирование', () => {
  for (const tag of DEVICES) {
    test(`Чек-лист «בדיקות לפני רכישה»: 8 пунктов, счётчик 0→3 из 8, localStorage #d4f37b ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);

      await expect(page.getByRole('heading', { level: 2, name: 'בדיקות לפני רכישה', exact: true })).toBeVisible();
      const boxes = page.locator('[role="checkbox"][id^="check-"]');
      await expect(boxes).toHaveCount(8);
      for (let i = 0; i < ITEMS.length; i++) {
        await expect(boxes.nth(i), `пункт ${i + 1}`).toContainText(ITEMS[i]);
      }
      await expect(page.getByText(/0 מתוך 8 הושלמו/)).toBeVisible();

      for (const name of ['אימות מחזור', 'שכירות', 'חובות']) {
        const box = boxes.filter({ hasText: name });
        await box.click();
        await expect(box).toHaveAttribute('aria-checked', 'true');
      }
      await expect(page.getByText(/3 מתוך 8/)).toBeVisible();

      await expect
        .poll(() => page.evaluate(() => localStorage.getItem('purchase-calculator-checklist')), {
          message: 'ключ purchase-calculator-checklist в localStorage',
        })
        .not.toBeNull();
    });
  }
});
